package com.kitchenos.connect.kitchen;

import org.json.*;
import java.util.*;
import java.math.BigDecimal;

/** Typed display/recipe data only. Hardware permission remains with ControlValues and ControlState. */
public final class MachineProgram {
    public static JSONObject validate(JSONObject program)throws Exception{
        if(program==null||program.toString().length()>262144||program.getInt("version")!=1||!program.getString("deviceModel").equals("xiaomi-c3"))throw new JSONException("Unbekanntes Maschinenrezept");
        text(program,"title",180);JSONObject source=program.getJSONObject("source");if(!source.getString("revision").matches("[a-f0-9]{64}"))throw new JSONException("Rezeptfassung fehlt");
        int portions=program.getInt("servings");if(portions<1||portions>20)throw new JSONException("Ungültige Portionszahl");
        JSONArray steps=program.getJSONArray("steps");if(steps.length()<1||steps.length()>40)throw new JSONException("Kochschritte fehlen");HashSet<String> ids=new HashSet<>();
        for(int i=0;i<steps.length();i++){
            JSONObject step=steps.getJSONObject(i);String id=text(step,"id",80),kind=step.getString("kind");if(!ids.add(id)||!Arrays.asList("prepare","weigh","machine","rest","finish").contains(kind))throw new JSONException("Schritt passt nicht zur Maschine");text(step,"title",160);text(step,"instruction",2400);
            JSONObject settings=step.getJSONObject("settings");Object seconds=settings.get("durationSeconds");if(seconds!=JSONObject.NULL&&(!(seconds instanceof Number)||((Number)seconds).doubleValue()!=((Number)seconds).intValue()||((Number)seconds).intValue()<1||((Number)seconds).intValue()>7200))throw new JSONException("Ungültige Laufzeit");
            if(kind.equals("machine")){if(seconds==JSONObject.NULL)throw new JSONException("Laufzeit fehlt");double temp=settings.getDouble("temperatureC"),speed=settings.getDouble("speedLevel");String direction=settings.getString("direction");if(!Double.isFinite(temp)||temp!=Math.rint(temp)||temp!=0&&(temp<35||temp>180)||!Double.isFinite(speed)||speed<0||speed>10||speed*2!=Math.rint(speed*2)||speed==0&&!direction.equals("none")||speed>0&&!Arrays.asList("clockwise","counterclockwise").contains(direction)||temp>=60&&speed>3)throw new JSONException("Unvollständige Maschineneinstellungen");}
            else if(!settings.isNull("temperatureC")||!settings.isNull("speedLevel")||!settings.isNull("direction"))throw new JSONException("Handgriff enthält Maschinenwerte");
            JSONArray ingredients=step.getJSONArray("ingredients");if(ingredients.length()>80)throw new JSONException("Zu viele Zutaten");for(int j=0;j<ingredients.length();j++){JSONObject item=ingredients.getJSONObject(j);text(item,"name",160);String unit=item.getString("unit");if(unit.length()>24)throw new JSONException("Ungültige Einheit");if(item.isNull("amount"))continue;double amount=item.getDouble("amount");if(!Double.isFinite(amount)||amount<=0||amount>1000000||unit.isEmpty())throw new JSONException("Ungültige Zutatenmenge");}
        }return program;
    }
    private static String text(JSONObject value,String key,int max)throws JSONException{String text=value.getString(key).trim();if(text.isEmpty()||text.length()>max||text.indexOf(0)>=0)throw new JSONException("Unvollständiger Rezepttext");return text;}
    public static JSONArray ingredients(JSONObject program)throws Exception{
        LinkedHashMap<String,JSONObject> all=new LinkedHashMap<>();JSONArray steps=program.getJSONArray("steps");
        for(int i=0;i<steps.length();i++){JSONArray uses=steps.getJSONObject(i).getJSONArray("ingredients");for(int j=0;j<uses.length();j++){JSONObject item=uses.getJSONObject(j);String key=item.getString("name")+"\n"+item.getString("unit");JSONObject previous=all.get(key);if(previous==null)all.put(key,new JSONObject(item.toString()));else if(previous.isNull("amount")||item.isNull("amount"))previous.put("amount",JSONObject.NULL);else previous.put("amount",new BigDecimal(previous.get("amount").toString()).add(new BigDecimal(item.get("amount").toString())));}}
        JSONArray result=new JSONArray();for(JSONObject value:all.values())result.put(value);return result;
    }
    public static boolean executable(JSONObject program){try{validate(program);JSONArray steps=program.getJSONArray("steps");for(int i=0;i<steps.length();i++){JSONObject step=steps.getJSONObject(i);if(step.getString("kind").equals("machine")){JSONObject settings=step.getJSONObject("settings");if(!com.kitchenos.connect.control.ControlProfile.supports(settings.getInt("durationSeconds"),settings.getInt("temperatureC"),(int)Math.round(settings.getDouble("speedLevel")*10)*(settings.getString("direction").equals("counterclockwise")?-1:1)))return false;}}return true;}catch(Exception e){return false;}}
    public static JSONObject card(JSONObject variant)throws Exception{JSONObject program=validate(variant.getJSONObject("program"));JSONObject card=new JSONObject().put("id",variant.getString("recipeId")).put("foodIdentity",variant.optString("foodIdentity",variant.getString("recipeId"))).put("title",program.getString("title")).put("coverUrl",program.getJSONObject("cover").getString("url")).put("ingredients",ingredients(program)).put("machineProgram",program).put("programDigest",variant.optString("programDigest")).put("reviewStatus",variant.optString("reviewStatus","ai-draft")).put("private",variant.optBoolean("private",false)).put("stepImagesMatch",variant.optBoolean("stepImagesMatch")).put("curated",variant.optBoolean("curated"));JSONObject nutrition=variant.optJSONObject("knownNutrition");if(nutrition==null)nutrition=program.optJSONObject("knownNutrition");if(nutrition!=null)card.put("knownNutrition",new JSONObject(nutrition.toString()));JSONObject timing=variant.optJSONObject("timing");if(timing!=null){boolean valid=true;for(String field:new String[]{"prepMinutes","cookMinutes","restMinutes"}){Object value=timing.opt(field);valid&=value instanceof Number&&((Number)value).doubleValue()>=0&&((Number)value).doubleValue()<=4320;}if(valid)card.put("timing",new JSONObject(timing.toString()));}if(variant.optJSONObject("importedRecipe")!=null)card.put("importedRecipe",variant.getJSONObject("importedRecipe"));return card;}
    public static com.kitchenos.common.Recipe asRecipe(JSONObject card)throws Exception{JSONObject program=validate(card.getJSONObject("machineProgram"));String digest=card.getString("programDigest"),id=digest.substring(0,8)+"-"+digest.substring(8,12)+"-"+digest.substring(12,16)+"-"+digest.substring(16,20)+"-"+digest.substring(20,32);JSONArray amounts=new JSONArray(),lines=new JSONArray(),items=ingredients(program),steps=program.getJSONArray("steps");for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);amounts.put((item.isNull("amount")?"":item.get("amount")+" "+item.optString("unit")+" ")+item.getString("name"));}for(int i=0;i<steps.length();i++){JSONObject step=steps.getJSONObject(i);lines.put(step.getString("title")+"\n"+step.getString("instruction"));}return new com.kitchenos.common.Recipe(id,program.getString("title"),program.getJSONObject("source").optString("url","").equals("null")?"":program.getJSONObject("source").optString("url",""),amounts,lines,program.getInt("servings"));}
    public static String toolName(String id){switch(id){case "mixing-blade":return "Messer";case "spatula":return "Spatel";case "oven":return "Backofen";case "air-fryer":return "Airfryer";case "pan":return "Pfanne";case "scale":return "Waage";case "steam-basket":return "Gareinsatz";case "steamer":return "Dampfaufsatz";case "stirring-attachment":return "Rühraufsatz";default:return id;}}
    private MachineProgram(){}
}
